def minTimeClearFlagged(s):
    n = len(s)
    left = [0] * (n + 1)
    for i in range(1, n + 1):
        left[i] = min(i, left[i - 1] + (2 if s[i - 1] == '1' else 0))
    right = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        right[i] = min(n - i, right[i + 1] + (2 if s[i] == '1' else 0))
    return min(left[i] + right[i] for i in range(n + 1))
